import { buildApp } from "../src/server.ts";
import { decideStatus, EventError, parseEvent, processEvent } from "../src/refunds.ts";
import { Store } from "../src/store.ts";
import { computeSignature, parseSignatureHeader, SignatureError, verifyWebhook } from "../src/verify.ts";

const SECRET = "whsec_regression";
const POLICY = { auto_approve_max_minor: 500000, auto_approve_currencies: ["INR"] };
function rawEvent(id: string, type = "refund.requested", amount = 500000) {
  return JSON.stringify({ event_id: id, type, created: 1731920000,
    data: { refund_id: "rf_test", payment_id: "pay_test", amount, currency: "INR" } });
}
function signed(raw: string | Buffer, timestamp = Math.floor(Date.now() / 1000), secret = SECRET) {
  return `t=${timestamp},v1=${computeSignature(secret, timestamp, raw)}`;
}
function snapshot(dir: string): unknown {
  return readdirSync(dir, { withFileTypes: true }).sort((a, b) => a.name.localeCompare(b.name)).map((entry) => {
    const path = join(dir, entry.name);
    return [entry.name, entry.isDirectory() ? snapshot(path) : readFileSync(path, "hex")];
  });
}

test("signature rotation accepts any configured secret and v1, and authenticates exact bytes", () => {
  const now = 1731920000;
  const raw = Buffer.from('{ "reason": "café", "amount": 123 }\n');
  const expected = createHmac("sha256", SECRET).update(Buffer.concat([Buffer.from(`${now}.`), raw])).digest("hex");
  assert.equal(computeSignature(SECRET, now, raw), expected);
  const header = `t=${now},v1=${"0".repeat(64)},v1=${expected}`;
  assert.doesNotThrow(() => verifyWebhook(raw, header, ["old_secret", SECRET], now));
  assert.throws(() => verifyWebhook(JSON.stringify(JSON.parse(raw.toString())), header, [SECRET], now), SignatureError);
  const invalidUtf8 = Buffer.from([0xff, 0xfe]);
  assert.throws(() => verifyWebhook(invalidUtf8, signed(invalidUtf8.toString(), now), [SECRET], now), SignatureError);
  assert.throws(() => verifyWebhook(raw, header, [], now), SignatureError);
});

test("timestamp tolerance is inclusive in both directions and configurable", () => {
  const now = 1731920000;
  for (const offset of [-300, 300]) {
    assert.doesNotThrow(() => verifyWebhook("{}", signed("{}", now + offset), [SECRET], now));
  }
  for (const offset of [-301, 301]) {
    assert.throws(() => verifyWebhook("{}", signed("{}", now + offset), [SECRET], now), SignatureError);
  }
  assert.throws(() => verifyWebhook("{}", signed("{}", now + 11), [SECRET], now, 10), SignatureError);
